INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 5, 'theory', 'Quiz: Operators, Type Coercion and Comparison');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 0, 'What are ''5'' + 1 and ''5'' - 1?', '["6 and 4", "''51'' and 4", "''51'' and ''4''", "6 and 6"]', 1, 'If there is a string, + concatenates; minus is always a numeric operator and converts the string to a number.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 1, 'What is -7 % 3?', '["2", "1", "-2", "-1"]', 3, 'The remainder takes the dividend''s sign, as in C; in Python the result would be 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 2, 'Why do [''10'', ''9'', ''1''].sort() and [10, 9, 1].sort() both give the order "1, 10, 9"?', '["sort compares elements as strings by default", "Because of an engine bug", "sort works only with strings", "sort sorts in descending order"]', 0, 'Without a comparison function, elements are converted to strings and compared by codes; for numbers you need (a, b) => a - b.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 3, 'What does 0 ?? 5 return, and what does 0 || 5 return?', '["5 and 5", "0 and 0", "0 and 5", "5 and 0"]', 2, '?? replaces only null and undefined, so 0 is kept; || replaces any falsy value.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 4, 'What does the expression 0 < x < 10 do when x = 15?', '["Returns false, like a range check", "Throws an exception", "Returns true: (0 < 15) → true, then true < 10", "Returns 15"]', 2, 'A comparison chain does not check a range: first you get a boolean, which is then converted to a number. Write x > 0 && x < 10.');
